package main

import("context";"encoding/json";"errors";"log";"os";"strings";"time";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/config";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/model";"github.com/nawyaunnam/cloudscale-distributed-job-processing/internal/store";"github.com/redis/go-redis/v9";"github.com/segmentio/kafka-go")
func main(){ctx:=context.Background();c:=config.Load();s,e:=store.New(ctx,c.DatabaseURL);if e!=nil{log.Fatal(e)};worker, _:=os.Hostname();rd:=redis.NewClient(&redis.Options{Addr:c.RedisAddr});reader:=kafka.NewReader(kafka.ReaderConfig{Brokers:strings.Split(c.KafkaBrokers,","),Topic:"jobs",GroupID:"cloudscale-workers",MinBytes:1,MaxBytes:10e6,CommitInterval:0});defer reader.Close();retry:=&kafka.Writer{Addr:kafka.TCP(strings.Split(c.KafkaBrokers,",")...),Topic:"jobs",RequiredAcks:kafka.RequireAll};dead:=&kafka.Writer{Addr:kafka.TCP(strings.Split(c.KafkaBrokers,",")...),Topic:"jobs.dlq",RequiredAcks:kafka.RequireAll};go recoverLeases(ctx,s,retry);for{m,e:=reader.FetchMessage(ctx);if e!=nil{log.Print(e);continue};var envelope model.Job;if json.Unmarshal(m.Value,&envelope)!=nil{dead.WriteMessages(ctx,m);reader.CommitMessages(ctx,m);continue};job,e:=s.Lease(ctx,envelope.ID,worker,30*time.Second);if e!=nil{reader.CommitMessages(ctx,m);continue};rd.Set(ctx,"worker:"+worker,time.Now().UTC().Format(time.RFC3339),45*time.Second);done:=make(chan struct{});go heartbeat(ctx,s,job.ID,worker,done);result,e:=execute(job);close(done);if e==nil{s.Complete(ctx,job.ID,worker,result)}else{again:=job.Attempt<job.MaxAttempts;s.Fail(ctx,job.ID,worker,e.Error(),again);if again{time.Sleep(time.Duration(job.Attempt)*time.Second);retry.WriteMessages(ctx,m)}else{dead.WriteMessages(ctx,m)}};reader.CommitMessages(ctx,m)}}
func execute(j model.Job)(map[string]any,error){switch j.Type{case"sleep":d,_:=time.ParseDuration(j.Payload["duration"].(string));if d>2*time.Minute{return nil,errors.New("duration exceeds limit")};time.Sleep(d);return map[string]any{"slept":d.String()},nil;case"checksum":return map[string]any{"accepted":true,"input":j.Payload},nil;default:return nil,errors.New("unsupported job type")}}
func heartbeat(ctx context.Context,s *store.Store,id,w string,done<-chan struct{}){t:=time.NewTicker(10*time.Second);defer t.Stop();for{select{case<-done:return;case<-t.C:s.Heartbeat(ctx,id,w,30*time.Second)}}}
func recoverLeases(ctx context.Context,s *store.Store,w *kafka.Writer){t:=time.NewTicker(15*time.Second);defer t.Stop();for range t.C{ids,_:=s.Recover(ctx);for _,id:=range ids{b,_:=json.Marshal(model.Job{ID:id});w.WriteMessages(ctx,kafka.Message{Key:[]byte(id),Value:b})}}}

